import{_ as h,C as o,o as d,c as E,a2 as a,b as l,w as e,a as n,E as i,a3 as s}from"./chunks/framework.CFuv5BrO.js";const g=JSON.parse('{"title":"Hearth OS · Agent 运行时设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-Agent运行时设计说明.md","filePath":"architecture/Hearth-Agent运行时设计说明.md","lastUpdated":null}'),c={name:"architecture/Hearth-Agent运行时设计说明.md"};function B(A,t,b,_,p,u){const r=o("Mermaid");return d(),E("div",null,[t[1]||(t[1]=a('<h1 id="hearth-os-·-agent-运行时设计说明" tabindex="-1">Hearth OS · Agent 运行时设计说明 <a class="header-anchor" href="#hearth-os-·-agent-运行时设计说明" aria-label="Permalink to &quot;Hearth OS · Agent 运行时设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>packages/agent-runtime/src</code> 全部文件），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>「进程内消息压缩」与「上下文账本」是两回事</td><td><a href="./hearth-os-上下文管理设计.html">hearth-os-上下文管理设计</a></td><td>只讲压缩算法本身，不重讲两者的区分</td></tr><tr><td>工具触发审批、向用户提问的下游路由</td><td><a href="./判定审批机制说明.html">判定审批机制说明</a></td><td>只讲工具定义与权限，不重讲审批</td></tr><tr><td>网页抓取与 HTML 净化的完整规则</td><td><a href="./Hearth-数据源与联网设计说明.html">Hearth-数据源与联网设计说明</a></td><td>这里只在工具清单中出现名字，规则交给那篇</td></tr><tr><td>检查点如何被调度器落盘与恢复校验</td><td><a href="./Hearth-任务执行调度器设计说明.html">Hearth-任务执行调度器设计说明</a></td><td>只讲运行时产出什么，不讲落盘</td></tr><tr><td>模型协议与执行器怎么接</td><td><a href="./Hearth-模型接入与执行器适配设计说明.html">Hearth-模型接入与执行器适配设计说明</a></td><td>不展开</td></tr></tbody></table><p>本文只讲：<strong>这个独立共享包里的「单 Agent 循环」是怎么转的、能用什么工具、被什么约束、怎么防止自己绕圈、怎么压缩记忆</strong>。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p>它是一个与服务端完全解耦的纯函数式循环库：给定模型适配器、一组工具、一份权限和一份预算，产出事件流、用量统计与检查点。它自己不碰数据库、不决定任务状态、不知道任务是什么——这些全由调度器负责。</p><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为它是服务端的「运行时框架」</td><td>它是共享包，不持有任何全局状态；名字相近的服务端 <code>runtime.ts</code> 其实是「装 Python/Node 依赖」的脚本编排器，两者毫无关系</td></tr><tr><td>以为工具清单固定可用</td><td>工具是「恒被定义」但「按权限筛选」的，能不能调用取决于权限里的工具名单</td></tr><tr><td>以为防死循环靠预算配置</td><td>防绕圈阈值硬编码在循环里，跟外部传入的运行预算是两套东西</td></tr></tbody></table><hr><h2 id="_2-主循环-一轮里发生什么" tabindex="-1">2. 主循环：一轮里发生什么 <a class="header-anchor" href="#_2-主循环-一轮里发生什么" aria-label="Permalink to &quot;2. 主循环：一轮里发生什么&quot;">​</a></h2>',13)),(d(),l(s,null,{default:e(()=>[i(r,{id:"mermaid-139",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E6%8E%A5%E6%94%B6%E6%A8%A1%E5%9E%8B%E9%80%82%E9%85%8D%E5%99%A8%20%C2%B7%20%E5%B7%A5%E5%85%B7%E9%9B%86%20%C2%B7%20%E6%9D%83%E9%99%90%20%C2%B7%20%E9%A2%84%E7%AE%97%5D%20--%3E%20B%5B%E6%9E%84%E9%80%A0%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%E4%B8%8E%E6%B6%88%E6%81%AF%E5%88%97%E8%A1%A8%5D%0A%20%20%20%20B%20--%3E%20C%5B%E8%AF%B7%E6%B1%82%E6%A8%A1%E5%9E%8B%E4%B8%80%E8%BD%AE%5D%0A%20%20%20%20C%20--%3E%20D%5B%E7%B4%AF%E7%A7%AF%E5%A2%9E%E9%87%8F%E6%96%87%E6%9C%AC%20%C2%B7%20%E6%8E%A8%E7%90%86%E7%89%87%E6%AE%B5%20%C2%B7%20%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%5D%0A%20%20%20%20D%20--%3E%20E%7B%E6%9C%89%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%3F%7D%0A%20%20%20%20E%20--%3E%7C%E6%9C%89%7C%20F%5B%E6%8C%89%E6%9D%83%E9%99%90%E6%9F%A5%E5%B7%A5%E5%85%B7%20%C2%B7%20%E6%89%A7%E8%A1%8C%20%C2%B7%20%E5%9B%9E%E5%A1%AB%E7%BB%93%E6%9E%9C%5D%0A%20%20%20%20F%20--%3E%20G%5B%E7%B4%AF%E8%AE%A1%E7%94%A8%E9%87%8F%20%C2%B7%20%E5%86%99%E6%A3%80%E6%9F%A5%E7%82%B9%5D%0A%20%20%20%20G%20--%3E%20C%0A%20%20%20%20E%20--%3E%7C%E6%97%A0%20%2F%20%E6%94%B6%E5%88%B0%E6%94%B6%E5%B0%BE%E5%B7%A5%E5%85%B7%7C%20H%5B%E5%88%A4%E5%AE%9A%E7%BB%88%E6%AD%A2%E7%8A%B6%E6%80%81%5D%0A%20%20%20%20H%20--%3E%20I%5B%E8%BE%93%E5%87%BA%E4%BA%8B%E4%BB%B6%E6%B5%81%E4%B8%8E%E6%9C%80%E7%BB%88%E7%BB%93%E8%AE%BA%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<p>对外发出的事件类型包括：一轮开始、文本增量、完整消息、工具开始、工具结束、检查点创建/失败、已压缩、用量、预算耗尽、提示。终止状态共五种：完成、等待补充、失败、取消、预算耗尽。</p><p><strong>四类防绕圈保护</strong>（都不来自外部预算）：</p><table tabindex="0"><thead><tr><th>现象</th><th>阈值</th></tr></thead><tbody><tr><td>相同工具调用签名连续重复</td><td>达到 2 次即停</td></tr><tr><td>只有文字声称完成、却没调收尾工具</td><td>连续超过 1 次判失败</td></tr><tr><td>模型返回空内容</td><td>连续 3 次判失败</td></tr><tr><td>收尾自检被拒</td><td>最多拒 2 次；模型临时错误最多重试 2 次</td></tr></tbody></table><hr><h2 id="_3-检查点与续跑" tabindex="-1">3. 检查点与续跑 <a class="header-anchor" href="#_3-检查点与续跑" aria-label="Permalink to &quot;3. 检查点与续跑&quot;">​</a></h2><p>检查点记录某一时刻的完整消息状态，共六种类型：一轮结束、一次工具结束、压缩后、最终结论、预算耗尽、等待补充。恢复时由调度器校验目标、权限摘要与副作用结算状态，再把用量、轮数、工具调用计数归零，避免历史消耗吃掉新一段预算。</p><hr><h2 id="_4-十六个内置工具" tabindex="-1">4. 十六个内置工具 <a class="header-anchor" href="#_4-十六个内置工具" aria-label="Permalink to &quot;4. 十六个内置工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>工具</th><th>作用</th></tr></thead><tbody><tr><td>读取</td><td>读文件、读文档、列目录、全文搜索、文件名匹配、内容正则</td><td>把工作区内容变成模型可消化的文本</td></tr><tr><td>写入</td><td>写文件、写表格、写文档、编辑文件、应用补丁</td><td>产出交付物</td></tr><tr><td>执行</td><td>命令行、截屏</td><td>跑脚本与获取桌面画面</td></tr><tr><td>联网</td><td>抓取网页</td><td>需显式网络权限才可用（净化规则见数据源文档）</td></tr><tr><td>交互</td><td>向用户提问</td><td>触发等待补充（审批与澄清见判定审批文档）</td></tr><tr><td>收尾</td><td>结束任务</td><td>声明本轮完成</td></tr></tbody></table><p>权限是四要素：<strong>可读根路径、可写根路径、允许的网络主机、允许的工具名单</strong>。路径校验会解析真实路径以防符号链接越界；工具在执行前先按名单过滤，未列名的一律视为不存在。</p><p>一个典型例子：抓取网页工具恒被定义，但默认权限构造器只在「允许网络主机不为空」时才把它放进工具名单。所以「有这个工具」不等于「能调用」。</p><hr><h2 id="_5-工具侧的硬性上限" tabindex="-1">5. 工具侧的硬性上限 <a class="header-anchor" href="#_5-工具侧的硬性上限" aria-label="Permalink to &quot;5. 工具侧的硬性上限&quot;">​</a></h2><p>这些数字决定了模型一次能看到多少东西：</p><table tabindex="0"><thead><tr><th>项</th><th>上限</th></tr></thead><tbody><tr><td>单文件读取</td><td>2 MB</td></tr><tr><td>目录列举 / 文件名匹配</td><td>各 500 条</td></tr><tr><td>全文搜索结果</td><td>100 条</td></tr><tr><td>正则模式长度 / 扫描时长</td><td>500 字符 / 10 秒</td></tr><tr><td>命令行输出</td><td>8 千字符</td></tr><tr><td>单个文档</td><td>25 MB，输出 20 万字符（读文档默认 8 万，可夹在 1 千至 20 万之间）</td></tr></tbody></table><p>命令行还有两道黑名单：一是危险命令（删除根目录、格式化磁盘、关机重启类），二是在<strong>没有网络权限时</strong>拒绝一切可能联网的命令（代码托管、克隆、下载、远程登录、文件传输等）。也就是说网络限制不只管抓取工具，也管 shell。</p><hr><h2 id="_6-两级压缩" tabindex="-1">6. 两级压缩 <a class="header-anchor" href="#_6-两级压缩" aria-label="Permalink to &quot;6. 两级压缩&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>第一级：字符压缩</th><th>第二级：带摘要的 token 压缩</th></tr></thead><tbody><tr><td>触发</td><td>每轮检查消息条数与总字符数</td><td>估算 token 超过「上下文窗口 − 保留区」</td></tr><tr><td>保留</td><td>末尾 30 条消息</td><td>末尾约 2 万 token 的近期消息</td></tr><tr><td>总量上限</td><td>12 万字符；超长的工具输出先截到 8 千字符并附截断说明</td><td>保留区取 1.6 万 token 与窗口 15% 中的较大者</td></tr><tr><td>特殊规则</td><td>消息不超过 36 条且字符未超限就直接跳过，不压缩</td><td>token 用「字符数 ÷ 4」向上取整估算； older 部分交给模型生成摘要</td></tr></tbody></table><p>两个容易读错的细节：字符压缩的提前返回条件是 <strong>36 条</strong>（保留数 + 6），不是 30 条；保留区不是固定 1.6 万，窗口越大它跟着涨。</p><hr><h2 id="_7-文档读写能力" tabindex="-1">7. 文档读写能力 <a class="header-anchor" href="#_7-文档读写能力" aria-label="Permalink to &quot;7. 文档读写能力&quot;">​</a></h2><p>读取支持纯文本、Markdown、CSV、JSON、HTML、PDF、Word、Excel；写出支持 Excel 与 Word。设计上有几个体贴的处理：</p><ul><li>文本解码先严格按 UTF-8，失败再回退到 GB18030，兼容国内常见旧文件。</li><li>CSV 会根据首行各分隔符出现次数自动判断逗号、制表符还是分号。</li><li>Excel 逐工作表转成 Markdown 表格，PDF 逐页取文本，Word 先转 HTML 再去图片。</li><li><strong>超限是「截断 + 记录缺口」，不是抛错</strong>：抽取上限 5 MB、Excel 5000 行 / 200 列、PDF 500 页，超出部分在结果里记一条缺口说明，让模型知道自己看的是不完整内容。只有写出侧的行列数、工作表数与文档段落数才会硬报错。</li><li>结果带一个「覆盖度」结构：是否完整、页数/段落数/工作表数、缺口列表。</li></ul><p>HTML 转 Markdown 时会删掉脚本、样式、导航、页脚、表单等噪声，把相对链接绝对化，再优先从正文容器中取内容。完整净化规则见<a href="./Hearth-数据源与联网设计说明.html">Hearth-数据源与联网设计说明</a>。</p><hr><h2 id="_8-只读代码才会发现的事实" tabindex="-1">8. 只读代码才会发现的事实 <a class="header-anchor" href="#_8-只读代码才会发现的事实" aria-label="Permalink to &quot;8. 只读代码才会发现的事实&quot;">​</a></h2><ol><li>「相同工具连续 2 次」「空返回 3 次」「收尾自检最多拒 2 次」都是硬编码，与运行预算无关，调预算不会改变这些行为。</li><li>抓取网页工具恒存在但默认不可用，能否调用取决于权限里的网络主机列表。</li><li>字符压缩的跳过阈值是 36 条消息，不是 30 条。</li><li>Excel / PDF 超限是截断并标注缺口，不是失败；这能保证「读得到一部分」优于「什么都读不到」。</li><li>该包不认识 MCP 工具与子代理工具，它们由扩展层追加进来（见<a href="./Hearth-MCP与任务委派设计说明.html">Hearth-MCP与任务委派设计说明</a>）。</li></ol><hr><h2 id="_9-与其它模块的分界" tabindex="-1">9. 与其它模块的分界 <a class="header-anchor" href="#_9-与其它模块的分界" aria-label="Permalink to &quot;9. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>模型适配器、工具数组、权限、运行预算、取消信号、待恢复检查点</td></tr><tr><td>输出</td><td>运行时事件流、检查点、用量统计、五种终止状态</td></tr><tr><td>不讲</td><td>模型协议（模型适配）、调度与落盘（执行调度器）、上下文账本（上下文）、审批（判定审批）、网页净化（数据源）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>主循环、防绕圈、事件与状态</td><td><code>packages/agent-runtime/src/runtime.ts</code></td></tr><tr><td>十六个工具与权限校验</td><td><code>packages/agent-runtime/src/tools.ts</code></td></tr><tr><td>两级压缩</td><td><code>packages/agent-runtime/src/compaction.ts</code></td></tr><tr><td>文档抽取与写出</td><td><code>packages/agent-runtime/src/documents.ts</code></td></tr><tr><td>网页抓取（规则见数据源文档）</td><td><code>packages/agent-runtime/src/web-fetch.ts</code></td></tr><tr><td>工具 / 事件 / 检查点类型契约</td><td><code>packages/agent-runtime/src/types.ts</code></td></tr><tr><td>包的统一导出</td><td><code>packages/agent-runtime/src/index.ts</code></td></tr></tbody></table>',34))])}const C=h(c,[["render",B]]);export{g as __pageData,C as default};
